               .start("CopyObjectResult", AwsNamespaces.S3)
               .elem("LastModified", ISO_FORMAT.format(copy.getLastModified()))
               .elem("ETag", copy.getETag())
               .end("CopyObjectResult")
               .build();
           .statusCode(200)
